# I will take the remaining items in the valid_candidates list
# I will process them in batches to stay within the 25-call limit

def take_remaining_items(start_idx, end_idx):
    global current_weight, taken_items
    for i in range(start_idx, end_idx):
        item = valid_candidates[i]
        if current_weight + item['weight'] <= CAPACITY:
            try:
                take_item(item['id'])
                current_weight += item['weight']
                taken_items.append(item['id'])
                print(f"Successfully took {item['id']} (Class {item['class']}): weight {item['weight']}, value {item['value']}. Total weight: {current_weight}")
            except Exception as e:
                # If the class is not allowed, we skip it
                if "not allowed" in str(e):
                    print(f"Skipping {item['id']} (Class {item['class']}): {e}")
                else:
                    print(f"Unexpected error taking {item['id']} (Class {item['class']}): {e}")

# Take items from index 20 to 29 (remaining items)
take_remaining_items(20, 29)

print(f"Final total weight: {current_weight}/{CAPACITY}")
print(f"Total value: {sum(item['value'] for item in taken_items)}")

finish()
